{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.pipeline_for_winter_wear_check as with meta_map AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MAX(L1_CATEGORY) AS l1_category, MAX(CATEGORY) AS category_raw, MAX(COGS) AS cogs_fallback FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ),uc_lkp AS ( SELECT UPPER(TRIM(SKUGROUP)) AS sku_group, MAX(CATEGORY) AS uc_category, MAX(COST_PRICE) AS cogs_per_unit, MAX(MRP) AS mrp FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ), collection_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, MAX(collection) AS collection FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 GROUP BY 1 ), flannel_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, MAX(helper1) AS helper1 FROM snitch_db.maplemonk.GS_HC_SKU_REMARKS WHERE helper1 IS NOT NULL GROUP BY 1 ), liquid_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, FROM snitch_db.maplemonk.GS_HC_SKU_REMARKS WHERE upper(REMARK) like \'%LIQU%\' GROUP BY 1 ),meta_final AS ( SELECT COALESCE(m.sku_group, u.sku_group) AS sku_group, m.l1_category, COALESCE(NULLIF(TRIM(m.category_raw), \'\'), NULLIF(TRIM(u.uc_category), \'\')) AS category, COALESCE(u.cogs_per_unit, m.cogs_fallback) AS cogs, u.mrp AS mrp FROM meta_map m FULL OUTER JOIN uc_lkp u ON m.sku_group = u.sku_group ),winter_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, FROM snitch_db.maplemonk.GS_HC_SKU_REMARKS WHERE upper(REMARK) like \'%WINTER%\' GROUP BY 1 ), metafields_lkp AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MAX(MATERIAL_NEW) AS meta1, MAX(FIT) AS meta2, MAX(COLLAR_NEW) AS meta3, MAX(DESIGNS) AS meta4, MAX(SLEEVE_TYPE) AS meta5 FROM snitch_db.maplemonk.metafields_data GROUP BY 1 ) select c.*,CASE WHEN wl.sku_group IS NOT NULL THEN \'Winter Wear\' WHEN cl.sku_group IS NOT NULL THEN \'Collection\' WHEN fh.sku_group IS NOT NULL THEN fh.helper1 WHEN upper(PJ.PRODUCT_NAME) LIKE\'%FLANNEL%\' then \'Flannel\' WHEN upper(PJ.PRODUCT_NAME) LIKE\'%TECHNICAL%\' then \'Technical\' ELSE NULL END AS cc2, CASE WHEN fh.sku_group IS NOT NULL THEN \'Flannel\' WHEN LOWER(mf.category) LIKE \'%hoodies%\' OR LOWER(mf.category) LIKE \'%jackets%\' OR LOWER(mf.category) LIKE \'%sweaters%\' OR LOWER(mf.category) LIKE \'%overshirts%\' OR LOWER(mf.category) LIKE \'%overshirt%\' OR LOWER(mf.category) LIKE \'%sweatshirts%\' OR LOWER(mf.category) LIKE \'%trench coat%\' THEN LOWER(mf.category) WHEN cl.sku_group IS NOT NULL THEN cl.collection WHEN upper(PJ.PRODUCT_NAME) LIKE\'%TECHNICAL%\' then \'TECHNICAL\' WHEN upper(PJ.PRODUCT_NAME) LIKE\'%FLANNEL%\' then \'Flannel\' ELSE NULL END AS cc, from snitch_db.maplemonk.production_pipeline_data_v2 c LEFT JOIN collection_lkp cl ON UPPER(TRIM(c.normalized_sku)) = cl.sku_group LEFT JOIN flannel_lkp fh ON UPPER(TRIM(c.normalized_sku)) = fh.sku_group LEFT JOIN liquid_lkp lq ON UPPER(TRIM(c.normalized_sku)) = lq.sku_group left join snitch_db.maplemonk.product_journey pj on c.normalized_sku = pj.sku_group LEFT JOIN meta_final mf ON c.normalized_sku = mf.sku_group LEFT JOIN metafields_lkp mt ON c.normalized_sku = mt.sku_group left join winter_lkp WL on c.sku_group = wl.sku_group ; create or replace table snitch_db.maplemonk.table_for_winter_and_collections_analysis as WITH wh_raw AS ( SELECT UPPER(TRIM( CASE WHEN UPPER(TRIM(SPLIT_PART(\"Item SkuCode\", \'-\', -1))) IN ( \'XS\',\'S\',\'M\',\'L\',\'XL\',\'XXL\',\'2XL\',\'3XL\',\'XXXL\',\'XXU\', \'4XL\',\'5XL\',\'6XL\',\'7XL\',\'8XL\', \'28\',\'30\',\'32\',\'34\',\'36\',\'38\',\'40\',\'42\',\'44\',\'46\',\'48\',\'50\' ) THEN REGEXP_REPLACE(\"Item SkuCode\", \'-[^-]+$\', \'\') ELSE \"Item SkuCode\" END )) AS sku_group, UPPER(TRIM(\"SIZE\")) AS raw_size, SUM(INVENTORY) AS qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE FACILITY IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND \"DATE\" = ( SELECT MAX(\"DATE\") FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE \"DATE\" <= CURRENT_DATE() ) GROUP BY 1, 2 ), wh_norm AS ( SELECT sku_group, CASE WHEN raw_size = \'2XL\' THEN \'XXL\' WHEN raw_size = \'XXXL\' THEN \'3XL\' WHEN raw_size = \'XXU\' THEN \'2XL\' WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'XXL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' ELSE raw_size END AS size_norm, qty FROM wh_raw ), wh_pivot AS ( SELECT sku_group, SUM(CASE WHEN size_norm = \'XS\' THEN qty ELSE 0 END) AS wh_xs, SUM(CASE WHEN size_norm = \'S\' THEN qty ELSE 0 END) AS wh_s, SUM(CASE WHEN size_norm = \'M\' THEN qty ELSE 0 END) AS wh_m, SUM(CASE WHEN size_norm = \'L\' THEN qty ELSE 0 END) AS wh_l, SUM(CASE WHEN size_norm = \'XL\' THEN qty ELSE 0 END) AS wh_xl, SUM(CASE WHEN size_norm = \'XXL\' THEN qty ELSE 0 END) AS wh_xxl, SUM(CASE WHEN size_norm = \'3XL\' THEN qty ELSE 0 END) AS wh_3xl, SUM(CASE WHEN size_norm = \'4XL\' THEN qty ELSE 0 END) AS wh_4xl, SUM(CASE WHEN size_norm = \'5XL\' THEN qty ELSE 0 END) AS wh_5xl, SUM(CASE WHEN size_norm = \'6XL\' THEN qty ELSE 0 END) AS wh_6xl, SUM(CASE WHEN size_norm = \'7XL\' THEN qty ELSE 0 END) AS wh_7xl, SUM(CASE WHEN size_norm = \'8XL\' THEN qty ELSE 0 END) AS wh_8xl, SUM(qty) AS wh_total FROM wh_norm GROUP BY sku_group ), store_raw AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, SUM(COALESCE(XS_UNITS,0)) + SUM(COALESCE(JIT_XS_UNITS,0)) AS store_xs, SUM(COALESCE(S_UNITS,0)) + SUM(COALESCE(JIT_S_UNITS,0)) AS store_s, SUM(COALESCE(M_UNITS,0)) + SUM(COALESCE(JIT_M_UNITS,0)) AS store_m, SUM(COALESCE(L_UNITS,0)) + SUM(COALESCE(JIT_L_UNITS,0)) AS store_l, SUM(COALESCE(XL_UNITS,0)) + SUM(COALESCE(JIT_XL_UNITS,0)) AS store_xl, SUM(COALESCE(XXL_UNITS,0)) + SUM(COALESCE(JIT_2XL_UNITS,0)) AS store_xxl, SUM(COALESCE(XL3_UNITS,0)) + SUM(COALESCE(JIT_3XL_UNITS,0)) AS store_3xl, SUM(COALESCE(XL4_UNITS,0)) + SUM(COALESCE(JIT_4XL_UNITS,0)) AS store_4xl, SUM(COALESCE(XL5_UNITS,0)) + SUM(COALESCE(JIT_5XL_UNITS,0)) AS store_5xl, SUM(COALESCE(XL6_UNITS,0)) + SUM(COALESCE(JIT_6XL_UNITS,0)) AS store_6xl, (SUM(COALESCE(XS_UNITS,0))+SUM(COALESCE(S_UNITS,0))+SUM(COALESCE(M_UNITS,0))+SUM(COALESCE(L_UNITS,0)) +SUM(COALESCE(XL_UNITS,0))+SUM(COALESCE(XXL_UNITS,0))+SUM(COALESCE(XL3_UNITS,0))+SUM(COALESCE(XL4_UNITS,0)) +SUM(COALESCE(XL5_UNITS,0))+SUM(COALESCE(XL6_UNITS,0)) +SUM(COALESCE(JIT_XS_UNITS,0))+SUM(COALESCE(JIT_S_UNITS,0))+SUM(COALESCE(JIT_M_UNITS,0))+SUM(COALESCE(JIT_L_UNITS,0)) +SUM(COALESCE(JIT_XL_UNITS,0))+SUM(COALESCE(JIT_2XL_UNITS,0))+SUM(COALESCE(JIT_3XL_UNITS,0))+SUM(COALESCE(JIT_4XL_UNITS,0)) +SUM(COALESCE(JIT_5XL_UNITS,0))+SUM(COALESCE(JIT_6XL_UNITS,0)) ) AS store_total FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE \"DATE\" = ( SELECT MAX(\"DATE\") FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE \"DATE\" <= CURRENT_DATE() ) GROUP BY 1 ), meta_map AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MAX(L1_CATEGORY) AS l1_category, MAX(CATEGORY) AS category_raw, MAX(COGS) AS cogs_fallback FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), uc_lkp AS ( SELECT UPPER(TRIM(SKUGROUP)) AS sku_group, MAX(CATEGORY) AS uc_category, MAX(COST_PRICE) AS cogs_per_unit, MAX(MRP) AS mrp FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ), meta_final AS ( SELECT COALESCE(m.sku_group, u.sku_group) AS sku_group, m.l1_category, COALESCE(NULLIF(TRIM(m.category_raw), \'\'), NULLIF(TRIM(u.uc_category), \'\')) AS category, COALESCE(u.cogs_per_unit, m.cogs_fallback) AS cogs, u.mrp AS mrp FROM meta_map m FULL OUTER JOIN uc_lkp u ON m.sku_group = u.sku_group ), metafields_lkp AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MAX(MATERIAL_NEW) AS meta1, MAX(FIT) AS meta2, MAX(COLLAR_NEW) AS meta3, MAX(DESIGNS) AS meta4, MAX(SLEEVE_TYPE) AS meta5 FROM snitch_db.maplemonk.metafields_data GROUP BY 1 ), live_lkp AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MIN(FINAL_LIVE_DATE) AS final_live_date FROM snitch_db.maplemonk.base_product GROUP BY 1 ), putaway_src AS ( SELECT UPPER(TRIM( CASE WHEN UPPER(TRIM(SPLIT_PART(\"Item Type skuCode\", \'-\', -1))) IN ( \'XS\',\'S\',\'M\',\'L\',\'XL\',\'XXL\',\'2XL\',\'3XL\',\'XXXL\',\'XXU\', \'4XL\',\'5XL\',\'6XL\',\'7XL\',\'8XL\', \'28\',\'30\',\'32\',\'34\',\'36\',\'38\',\'40\',\'42\',\'44\',\'46\',\'48\',\'50\' ) THEN REGEXP_REPLACE(\"Item Type skuCode\", \'-[^-]+$\', \'\') ELSE \"Item Type skuCode\" END )) AS sku_group, \"PUTAWAY_UPDATED\"::DATE AS putaway_date, FINAL_TYPE, \"PUTAWAY_COMPLETED_QUANTITY\" AS qty FROM snitch_db.maplemonk.putaway_tracking ), inward_raw AS ( SELECT sku_group, putaway_date AS inward_date, SUM(qty) AS qty FROM putaway_src WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1, 2 ), inward_agg AS ( SELECT sku_group, MAX(inward_date) AS last_inward_date FROM inward_raw WHERE qty > 50 GROUP BY sku_group ), ageing_src AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, CASE WHEN TRIM(AGEING_BUCKET::VARCHAR) = \'0\' THEN \'0-30\' ELSE TRIM(AGEING_BUCKET::VARCHAR) END AS bucket FROM snitch_db.maplemonk.daily_fifo_ageing WHERE \"DATE\" = ( SELECT MAX(\"DATE\") FROM snitch_db.maplemonk.daily_fifo_ageing WHERE \"DATE\" <= CURRENT_DATE() ) ), ageing_lkp AS ( SELECT sku_group, MAX_BY( bucket, CASE bucket WHEN \'0-30\' THEN 1 WHEN \'30-60\' THEN 2 WHEN \'60-90\' THEN 3 WHEN \'90-120\' THEN 4 WHEN \'120-180\' THEN 5 WHEN \'180-270\' THEN 6 WHEN \'270-360\' THEN 7 WHEN \'360+\' THEN 8 END ) AS ageing_bucket FROM ageing_src GROUP BY sku_group ), wh_open AS ( SELECT UPPER(TRIM( CASE WHEN UPPER(TRIM(SPLIT_PART(\"Item SkuCode\", \'-\', -1))) IN ( \'XS\',\'S\',\'M\',\'L\',\'XL\',\'XXL\',\'2XL\',\'3XL\',\'XXXL\',\'XXU\', \'4XL\',\'5XL\',\'6XL\',\'7XL\',\'8XL\', \'28\',\'30\',\'32\',\'34\',\'36\',\'38\',\'40\',\'42\',\'44\',\'46\',\'48\',\'50\' ) THEN REGEXP_REPLACE(\"Item SkuCode\", \'-[^-]+$\', \'\') ELSE \"Item SkuCode\" END )) AS sku_group, SUM(INVENTORY) AS open_qty FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE FACILITY IN (\'SAPL-WH2\', \'SAPL-WH1\', \'SAPL-NORTH-TAURU\') AND \"DATE\" = \'2026-07-01\' GROUP BY 1 ), store_open AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, SUM( COALESCE(XS_UNITS,0)+COALESCE(S_UNITS,0)+COALESCE(M_UNITS,0)+COALESCE(L_UNITS,0) +COALESCE(XL_UNITS,0)+COALESCE(XXL_UNITS,0)+COALESCE(XL3_UNITS,0)+COALESCE(XL4_UNITS,0) +COALESCE(XL5_UNITS,0)+COALESCE(XL6_UNITS,0) +COALESCE(JIT_XS_UNITS,0)+COALESCE(JIT_S_UNITS,0)+COALESCE(JIT_M_UNITS,0)+COALESCE(JIT_L_UNITS,0) +COALESCE(JIT_XL_UNITS,0)+COALESCE(JIT_2XL_UNITS,0)+COALESCE(JIT_3XL_UNITS,0)+COALESCE(JIT_4XL_UNITS,0) +COALESCE(JIT_5XL_UNITS,0)+COALESCE(JIT_6XL_UNITS,0) ) AS open_qty FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE \"DATE\" = \'2026-07-01\' GROUP BY 1 ), inward_since AS ( SELECT sku_group, SUM(qty) AS inward_qty FROM inward_raw WHERE qty > 50 AND inward_date > \'2026-07-01\' GROUP BY sku_group ), returns_l30 AS ( SELECT sku_group, SUM(qty) AS returns_qty FROM putaway_src WHERE LOWER(FINAL_TYPE) LIKE \'b2c return%\' AND putaway_date >= DATEADD(day, -30, CURRENT_DATE()) AND putaway_date <= CURRENT_DATE() GROUP BY sku_group ), sales_src AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, TYPE AS channel, \"DATE\"::DATE AS sale_date, GROSS_QUANTITY AS qty, GROSS_SALES AS revenue FROM snitch_db.maplemonk.horizontal_sales_categories WHERE TYPE IN (\'Shopify\', \'Store\', \'Marketplace\') ), first_dates AS ( SELECT sku_group, MIN(CASE WHEN channel = \'Shopify\' THEN sale_date END) AS first_shopify, MIN(CASE WHEN channel = \'Store\' THEN sale_date END) AS first_store, MIN(CASE WHEN channel = \'Marketplace\' THEN sale_date END) AS first_marketplace, MIN(sale_date) AS first_all FROM sales_src WHERE qty > 0 GROUP BY sku_group ), sales_l30 AS ( SELECT sku_group, SUM(IFF(channel = \'Shopify\', qty, 0)) AS l30_qty_shopify, SUM(IFF(channel = \'Store\', qty, 0)) AS l30_qty_store, SUM(IFF(channel = \'Marketplace\', qty, 0)) AS l30_qty_marketplace, SUM(qty) AS l30_qty_total, SUM(IFF(channel = \'Shopify\', revenue, 0)) AS l30_rev_shopify, SUM(IFF(channel = \'Store\', revenue, 0)) AS l30_rev_store, SUM(IFF(channel = \'Marketplace\', revenue, 0)) AS l30_rev_marketplace, SUM(revenue) AS l30_rev_total FROM sales_src WHERE sale_date >= DATEADD(day, -30, CURRENT_DATE()) GROUP BY sku_group ), sales_l7 AS ( SELECT sku_group, SUM(IFF(channel = \'Shopify\', qty, 0)) AS l7_qty_shopify, SUM(IFF(channel = \'Store\', qty, 0)) AS l7_qty_store, SUM(IFF(channel = \'Marketplace\', qty, 0)) AS l7_qty_marketplace, SUM(qty) AS l7_qty_total, SUM(IFF(channel = \'Shopify\', revenue, 0)) AS l7_rev_shopify, SUM(IFF(channel = \'Store\', revenue, 0)) AS l7_rev_store, SUM(IFF(channel = \'Marketplace\', revenue, 0)) AS l7_rev_marketplace, SUM(revenue) AS l7_rev_total FROM sales_src WHERE sale_date >= DATEADD(day, -7, CURRENT_DATE()) GROUP BY sku_group ), sales_life AS ( SELECT sku_group, SUM(IFF(channel = \'Shopify\', qty, 0)) AS life_qty_shopify, SUM(IFF(channel = \'Store\', qty, 0)) AS life_qty_store, SUM(IFF(channel = \'Marketplace\', qty, 0)) AS life_qty_marketplace, SUM(qty) AS life_qty_total, SUM(IFF(channel = \'Shopify\', revenue, 0)) AS life_rev_shopify, SUM(IFF(channel = \'Store\', revenue, 0)) AS life_rev_store, SUM(IFF(channel = \'Marketplace\', revenue, 0)) AS life_rev_marketplace, SUM(revenue) AS life_rev_total FROM sales_src GROUP BY sku_group ), sales_since AS ( SELECT sku_group, SUM(qty) AS qty_total FROM sales_src WHERE sale_date > \'2026-07-01\' GROUP BY sku_group ), sales_f30 AS ( SELECT s.sku_group, SUM(IFF(s.channel = \'Shopify\' AND s.sale_date BETWEEN f.first_shopify AND DATEADD(day, 29, f.first_shopify), s.qty, 0)) AS f30_qty_shopify, SUM(IFF(s.channel = \'Store\' AND s.sale_date BETWEEN f.first_store AND DATEADD(day, 29, f.first_store), s.qty, 0)) AS f30_qty_store, SUM(IFF(s.channel = \'Marketplace\' AND s.sale_date BETWEEN f.first_marketplace AND DATEADD(day, 29, f.first_marketplace), s.qty, 0)) AS f30_qty_marketplace, SUM(IFF(s.sale_date BETWEEN f.first_all AND DATEADD(day, 29, f.first_all), s.qty, 0)) AS f30_qty_total FROM sales_src s JOIN first_dates f ON s.sku_group = f.sku_group GROUP BY s.sku_group ), t_main AS ( SELECT _airbyte_data:\"Channel Ledger\"::STRING AS channel_ledger, _airbyte_data:\"Entity\"::STRING AS entity, _airbyte_data:\"Facility\"::STRING AS facility, NULLIF(_airbyte_data:\"GRN Price Without Tax\"::STRING, \'\')::FLOAT AS grn_price_without_tax, NULLIF(_airbyte_data:\"MRP\"::STRING, \'\')::FLOAT AS mrp, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP AS original_created_date, TRY_TO_DATE(_airbyte_data:\"Original_Invoice_Date\"::VARCHAR, \'DD-MM-YYYY\') AS original_invoice_date, _airbyte_data:\"Product SKU Code\"::STRING AS product_sku_code, NULLIF(_airbyte_data:\"Quantity\"::STRING, \'\')::INTEGER AS quantity, _airbyte_data:\"Sale Order Number\"::STRING AS sale_order_number, NULLIF(_airbyte_data:\"Sales\"::STRING, \'\')::FLOAT AS sales, NULLIF(_airbyte_data:\"Total\"::STRING, \'\')::FLOAT AS total FROM snitch_db.maplemonk._AIRBYTE_RAW_UC_AARYAN_GET_TALLY_GST_REPORT QUALIFY ROW_NUMBER() OVER ( PARTITION BY _airbyte_data:\"Sale Order Number\"::STRING, _airbyte_data:\"Product SKU Code\"::STRING, _airbyte_data:\"Warehouse Name\"::STRING, _airbyte_data:\"Original_Created_Date\"::TIMESTAMP ORDER BY _airbyte_data:\"Ingested At\"::TIMESTAMP DESC ) = 1 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_JAN206_MAY20260502 UNION ALL SELECT GET(VARIANT_COL, \'Channel Ledger\')::STRING AS channel_ledger, GET(VARIANT_COL, \'Entity\')::STRING AS entity, GET(VARIANT_COL, \'Facility\')::STRING AS facility, GET(VARIANT_COL, \'GRN Price Without Tax\')::FLOAT AS grn_price_without_tax, GET(VARIANT_COL, \'MRP\')::FLOAT AS mrp, GET(VARIANT_COL, \'Original_Created_Date\')::TIMESTAMP AS original_created_date, TO_DATE(GET(VARIANT_COL, \'Original_Invoice_Date\')::VARCHAR, \'DD-MM-YYYY\') AS original_invoice_date, GET(VARIANT_COL, \'Product SKU Code\')::STRING AS product_sku_code, GET(VARIANT_COL, \'Quantity\')::INT AS quantity, GET(VARIANT_COL, \'Sale Order Number\')::STRING AS sale_order_number, GET(VARIANT_COL, \'Sales\')::FLOAT AS sales, GET(VARIANT_COL, \'Total\')::FLOAT AS total FROM snitch_db.MAPLEMONK.mis_feb_20260504 UNION ALL SELECT channel_ledger, entity, facility, grn_price_without_tax, mrp, original_created_date, TO_DATE(Original_Invoice_Date, \'DD-MM-YYYY\') AS original_invoice_date, product_sku_code, quantity, sale_order_number, sales, total FROM snitch_db.MAPLEMONK.MIS_20260428 ), t_cost_price_map AS ( SELECT sku_group, cost_price, category FROM SNITCH_DB.MAPLEMONK.base_product QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY cost_price DESC ) = 1 ), t_mp_gross AS ( SELECT a.original_invoice_date AS date, TRIM(UPPER( REVERSE(SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code) )) )) AS sku_group, CASE WHEN a.channel_ledger IN (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\') THEN \'MP_Ajio\' WHEN a.channel_ledger IN (\'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\') THEN \'MP_Amazon\' WHEN a.channel_ledger IN (\'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\') THEN \'MP_Flipkart_PPMP\' WHEN a.channel_ledger IN (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') THEN \'MP_Myntra_PPMP\' WHEN a.channel_ledger IN ( \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) THEN \'MP_Nykaa\' ELSE \'others\' END AS channel, SUM( CASE WHEN a.channel_ledger IN ( \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\' ) THEN a.total WHEN a.channel_ledger IN (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') AND a.original_invoice_date >= \'2026-03-26\' THEN a.total + a.quantity * c.avg_cat_charges WHEN a.channel_ledger IN (\'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\') THEN a.total WHEN a.channel_ledger IN (\'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\') THEN (a.total / 0.82)::INT WHEN a.channel_ledger IN (\'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\') THEN (a.total / 0.68)::INT ELSE a.sales END )::INT AS sales, SUM( COALESCE(TRY_TO_NUMBER(NULLIF(REGEXP_REPLACE(a.grn_price_without_tax, \'[^0-9.-]\', \'\'), \'\')), 0) * COALESCE(TRY_TO_NUMBER(NULLIF(REGEXP_REPLACE(a.quantity, \'[^0-9.-]\', \'\'), \'\')), 0) ) AS cp FROM t_main a LEFT JOIN t_cost_price_map b ON TRIM(UPPER( REVERSE(SUBSTRING( REVERSE(a.product_sku_code), CHARINDEX(\'-\', REVERSE(a.product_sku_code)) + 1, LEN(a.product_sku_code) )) )) = b.sku_group LEFT JOIN snitch_db.maplemonk.AVG_GT_CHARGES c ON b.category = c.category WHERE a.channel_ledger IN ( \'AJIO_SAPL_TAURU\', \'SAPL_AJIO_OMNI\', \'SAPL_AJIO_OMNI_2\', \'AMAZON_FLEX_WH2\', \'AMAZON_SAPL\', \'MYNTRAPPMP_SAPL_TAURU\', \'MYNTRAPPMP_SAPL-WH2\', \'SAPL_MYNTRA\', \'NYKAA_COM_SAPLWH\', \'NYKAA_COM_WH2\', \'NYKAA_FASHION_SAPL_TAURU\', \'NYKAA_FASHION_WH\', \'NYKAA_FASHION_WH2\', \'NYKAA_SAPL_TAURU\', \'FLIPKART_SAPLWH2\', \'SAPL_EMIZA_FLIPKART\', \'SAPL_FLIPKART\', \'FLIPKART_TAURU\' ) GROUP BY 1, 2, 3 ), t_slikk AS ( SELECT TO_DATE(order_date, \'DD-MM-YYYY\') AS date, UPPER(TRIM(a.\"Style \")) AS sku_group, \'MP_slikk\' AS channel, SUM(total_amount) AS sales, SUM(\"COGSxQty \") AS cp FROM snitch_db.maplemonk.google_sheets_slikk a GROUP BY 1, 2, 3 ), t_mp_rows AS ( SELECT date, sku_group, sales, cp FROM t_mp_gross WHERE channel LIKE \'MP%\' AND channel NOT LIKE \'%SOR%\' UNION ALL SELECT date, sku_group, sales, cp FROM t_slikk WHERE channel LIKE \'MP%\' AND channel NOT LIKE \'%SOR%\' ), t_mp_l30 AS ( SELECT sku_group, SUM(sales) AS mp_sales, SUM(cp) AS mp_cost FROM t_mp_rows WHERE date >= DATEADD(day, -30, CURRENT_DATE()) GROUP BY sku_group ), t_mp_l7 AS ( SELECT sku_group, SUM(sales) AS mp_sales, SUM(cp) AS mp_cost FROM t_mp_rows WHERE date >= DATEADD(day, -7, CURRENT_DATE()) GROUP BY sku_group ), t_mp_life AS ( SELECT sku_group, SUM(sales) AS mp_sales, SUM(cp) AS mp_cost FROM t_mp_rows GROUP BY sku_group ), pipeline_rows AS ( SELECT UPPER(TRIM(NORMALIZED_SKU)) AS sku_group, COALESCE(TRY_TO_NUMBER(REPLACE(TRIM(QTY::VARCHAR), \',\', \'\')), 0) AS qty, CASE WHEN UPPER(TRIM(ORDER_TYPE::VARCHAR)) LIKE \'REPEAT%\' OR UPPER(TRIM(ORDER_TYPE::VARCHAR)) LIKE \'MP%\' OR UPPER(TRIM(ORDER_TYPE::VARCHAR)) LIKE \'NOOS%\' OR REPLACE(UPPER(TRIM(ORDER_TYPE::VARCHAR)), \' \', \'\') LIKE \'MARKETPLACE%\' OR REPLACE(UPPER(TRIM(ORDER_TYPE::VARCHAR)), \' \', \'\') = \'B2B-CORP\' THEN TRIM(ORDER_TYPE::VARCHAR) END AS matched_order_type FROM snitch_db.maplemonk.production_pipeline_data_v2 WHERE NORMALIZED_SKU IS NOT NULL ), pipeline_lkp AS ( SELECT sku_group, SUM(qty) AS pipeline_qty, LISTAGG(DISTINCT matched_order_type, \', \') WITHIN GROUP (ORDER BY matched_order_type) AS pipeline_order_type FROM pipeline_rows GROUP BY sku_group ) , store_alloc AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, SUM(SUBORDER_QUANTITY) AS lifetime_store_allocated_qty FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE WHERE MARKETPLACE IN ( \'FRANCHISE_STORE\', \'FRANCHISE_STORE_B2B\', \'Franchise Store\', \'OWN_STORE\', \'OWN_STORE_B2B\', \'Own Store\' ) AND UPPER(TRIM(SKU_GROUP)) NOT LIKE \'MP-%\' AND UPPER(TRIM(REGEXP_REPLACE(ORDER_ID, \'[-_/ ]*[0-9]+$\', \'\'))) NOT IN ( \'SO\', \'QC-HSRLAY\', \'QC-SECTOR\', \'QC-MFCHYD\', \'QC-INDIRA\', \'QC-JANAKP\', \'QC-CGROAD\', \'QC-KALYAN\', \'QC-DAHISA\', \'4MSS\', \'QC-DAHISAQ\', \'LINROAWH2\' ) GROUP BY 1 ), store_returns AS ( SELECT UPPER(TRIM( REVERSE(SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") )) )) AS sku_group, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS returns_lifetime FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'store return%\' AND UPPER(TRIM(\"Item Type skuCode\")) NOT LIKE \'MP-%\' GROUP BY 1 ), offline_by_mp AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MARKETPLACE_MAPPED, SUM(COALESCE(INVENTORY, 0)) AS inventory_qty, SUM(COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0)) AS inv_jit_qty FROM snitch_db.maplemonk.offline_master GROUP BY 1, 2 ), offline_summary AS ( SELECT sku_group, SUM(inventory_qty) AS offline_inventory_qty, COUNT(DISTINCT CASE WHEN inv_jit_qty > 0 THEN MARKETPLACE_MAPPED END) AS marketplace_mapped_with_stock FROM offline_by_mp GROUP BY 1 ), combined AS ( SELECT COALESCE(w.sku_group, s.sku_group) AS sku_group, COALESCE(w.wh_xs,0) + COALESCE(s.store_xs,0) AS total_xs, COALESCE(w.wh_s,0) + COALESCE(s.store_s,0) AS total_s, COALESCE(w.wh_m,0) + COALESCE(s.store_m,0) AS total_m, COALESCE(w.wh_l,0) + COALESCE(s.store_l,0) AS total_l, COALESCE(w.wh_xl,0) + COALESCE(s.store_xl,0) AS total_xl, COALESCE(w.wh_xxl,0) + COALESCE(s.store_xxl,0) AS total_xxl, COALESCE(w.wh_3xl,0) + COALESCE(s.store_3xl,0) AS total_3xl, COALESCE(w.wh_4xl,0) + COALESCE(s.store_4xl,0) AS total_4xl, COALESCE(w.wh_5xl,0) + COALESCE(s.store_5xl,0) AS total_5xl, COALESCE(w.wh_6xl,0) + COALESCE(s.store_6xl,0) AS total_6xl, COALESCE(w.wh_7xl,0) AS total_7xl, COALESCE(w.wh_8xl,0) AS total_8xl, COALESCE(w.wh_xs,0) AS wh_sz_xs, COALESCE(w.wh_s,0) AS wh_sz_s, COALESCE(w.wh_m,0) AS wh_sz_m, COALESCE(w.wh_l,0) AS wh_sz_l, COALESCE(w.wh_xl,0) AS wh_sz_xl, COALESCE(w.wh_xxl,0) AS wh_sz_xxl, COALESCE(w.wh_3xl,0) AS wh_sz_3xl, COALESCE(w.wh_4xl,0) AS wh_sz_4xl, COALESCE(w.wh_5xl,0) AS wh_sz_5xl, COALESCE(w.wh_6xl,0) AS wh_sz_6xl, COALESCE(w.wh_7xl,0) AS wh_sz_7xl, COALESCE(w.wh_8xl,0) AS wh_sz_8xl, COALESCE(w.wh_total,0) AS wh_inv, COALESCE(s.store_total,0) AS store_inv, COALESCE(w.wh_total,0) + COALESCE(s.store_total,0) AS grand_total FROM wh_pivot w FULL OUTER JOIN store_raw s ON w.sku_group = s.sku_group ), size_flags AS ( SELECT c.sku_group, IFF(c.wh_sz_xs > 0, 1, 0) + IFF(c.wh_sz_s > 0, 1, 0) + IFF(c.wh_sz_m > 0, 1, 0) + IFF(c.wh_sz_l > 0, 1, 0) + IFF(c.wh_sz_xl > 0, 1, 0) + IFF(c.wh_sz_xxl > 0, 1, 0) + IFF(c.wh_sz_3xl > 0, 1, 0) + IFF(c.wh_sz_4xl > 0, 1, 0) + IFF(c.wh_sz_5xl > 0, 1, 0) + IFF(c.wh_sz_6xl > 0, 1, 0) + IFF(c.wh_sz_7xl > 0, 1, 0) + IFF(c.wh_sz_8xl > 0, 1, 0) AS sizes_avl, GREATEST(c.wh_sz_xs, c.wh_sz_s, c.wh_sz_m, c.wh_sz_l, c.wh_sz_xl, c.wh_sz_xxl, c.wh_sz_3xl, c.wh_sz_4xl, c.wh_sz_5xl, c.wh_sz_6xl, c.wh_sz_7xl, c.wh_sz_8xl) / NULLIF(c.wh_inv, 0) AS max_size_share FROM combined c ), ecosystem_cut AS ( SELECT c.sku_group, UPPER(TRIM(mf.category)) IN ( \'PERFUMES\', \'CAPS\', \'BAGS\', \'ACCESSORIES\', \'SUNGLASSES\', \'LUGGAGE\' ) AS is_excluded, CASE WHEN UPPER(TRIM(mf.category)) IN ( \'PERFUMES\', \'CAPS\', \'BAGS\', \'ACCESSORIES\', \'SUNGLASSES\', \'LUGGAGE\' ) THEN NULL WHEN UPPER(c.sku_group) LIKE \'SH0%\' THEN GREATEST( LEAST( ROUND((c.wh_sz_s - 1)/2.0), ROUND((c.wh_sz_m - 1)/2.0), ROUND((c.wh_sz_l - 1)/2.0), ROUND((c.wh_sz_xl - 1)/2.0) ), 0 ) WHEN UPPER(TRIM(mf.l1_category)) = \'PLUS\' THEN LEAST( ROUND(c.wh_sz_3xl/3.0), ROUND(c.wh_sz_4xl/3.0), ROUND(c.wh_sz_5xl/2.0), ROUND(c.wh_sz_6xl/2.0) ) WHEN UPPER(TRIM(mf.category)) = \'JEANS\' THEN CASE WHEN LEAST(ROUND(c.wh_sz_s/3.0), ROUND(c.wh_sz_m/4.0), ROUND(c.wh_sz_l/4.0), ROUND(c.wh_sz_xl/3.0)) > 0 THEN LEAST(ROUND(c.wh_sz_s/3.0), ROUND(c.wh_sz_m/4.0), ROUND(c.wh_sz_l/4.0), ROUND(c.wh_sz_xl/3.0)) ELSE GREATEST( LEAST(ROUND(c.wh_sz_xs/2.0), ROUND(c.wh_sz_s/3.0), ROUND(c.wh_sz_m/4.0), ROUND(c.wh_sz_l/4.0)), LEAST(ROUND(c.wh_sz_s/3.0), ROUND(c.wh_sz_m/4.0), ROUND(c.wh_sz_l/4.0), ROUND(c.wh_sz_xl/3.0)), LEAST(ROUND(c.wh_sz_m/4.0), ROUND(c.wh_sz_l/4.0), ROUND(c.wh_sz_xl/3.0), ROUND(c.wh_sz_xxl/2.0)) ) END ELSE LEAST( ROUND(c.wh_sz_s/3.0), ROUND(c.wh_sz_m/4.0), ROUND(c.wh_sz_l/4.0), ROUND(c.wh_sz_xl/3.0) ) END AS size_set_count, CASE WHEN UPPER(TRIM(mf.category)) IN ( \'PERFUMES\', \'CAPS\', \'BAGS\', \'ACCESSORIES\', \'SUNGLASSES\', \'LUGGAGE\' ) THEN NULL WHEN UPPER(c.sku_group) LIKE \'SH0%\' THEN GREATEST( LEAST( ROUND((c.wh_sz_s - 1)/2.0), ROUND((c.wh_sz_m - 1)/2.0), ROUND((c.wh_sz_l - 1)/2.0), ROUND((c.wh_sz_xl - 1)/2.0) ), 0 ) WHEN UPPER(TRIM(mf.l1_category)) = \'PLUS\' THEN LEAST( ROUND(c.wh_sz_3xl/2.0), ROUND(c.wh_sz_4xl/2.0), ROUND(c.wh_sz_5xl/1.0), ROUND(c.wh_sz_6xl/1.0) ) WHEN UPPER(TRIM(mf.category)) = \'JEANS\' THEN CASE WHEN LEAST(ROUND(c.wh_sz_s/1.0), ROUND(c.wh_sz_m/2.0), ROUND(c.wh_sz_l/2.0), ROUND(c.wh_sz_xl/1.0)) > 0 THEN LEAST(ROUND(c.wh_sz_s/1.0), ROUND(c.wh_sz_m/2.0), ROUND(c.wh_sz_l/2.0), ROUND(c.wh_sz_xl/1.0)) ELSE GREATEST( LEAST(ROUND(c.wh_sz_xs/1.0), ROUND(c.wh_sz_s/1.0), ROUND(c.wh_sz_m/2.0), ROUND(c.wh_sz_l/2.0)), LEAST(ROUND(c.wh_sz_s/1.0), ROUND(c.wh_sz_m/2.0), ROUND(c.wh_sz_l/2.0), ROUND(c.wh_sz_xl/1.0)), LEAST(ROUND(c.wh_sz_m/2.0), ROUND(c.wh_sz_l/2.0), ROUND(c.wh_sz_xl/1.0), ROUND(c.wh_sz_xxl/1.0)) ) END ELSE LEAST( ROUND(c.wh_sz_s/1.0), ROUND(c.wh_sz_m/2.0), ROUND(c.wh_sz_l/2.0), ROUND(c.wh_sz_xl/1.0) ) END AS size_set_revised FROM combined c LEFT JOIN meta_final mf ON c.sku_group = mf.sku_group ), margin_base AS ( SELECT c.sku_group, IFF(m30.mp_sales > 0 AND m30.mp_cost IS NOT NULL, m30.mp_sales, COALESCE(l.l30_rev_marketplace, 0)) AS mp30_rev, IFF(m30.mp_sales > 0 AND m30.mp_cost IS NOT NULL, m30.mp_cost, IFF(COALESCE(l.l30_qty_marketplace, 0) > 0, mfc.cogs * l.l30_qty_marketplace, 0)) AS mp30_cost, IFF(m7.mp_sales > 0 AND m7.mp_cost IS NOT NULL, m7.mp_sales, COALESCE(l7.l7_rev_marketplace, 0)) AS mp7_rev, IFF(m7.mp_sales > 0 AND m7.mp_cost IS NOT NULL, m7.mp_cost, IFF(COALESCE(l7.l7_qty_marketplace, 0) > 0, mfc.cogs * l7.l7_qty_marketplace, 0)) AS mp7_cost, IFF(mlf.mp_sales > 0 AND mlf.mp_cost IS NOT NULL, mlf.mp_sales, COALESCE(lf.life_rev_marketplace, 0)) AS mplife_rev, IFF(mlf.mp_sales > 0 AND mlf.mp_cost IS NOT NULL, mlf.mp_cost, IFF(COALESCE(lf.life_qty_marketplace, 0) > 0, mfc.cogs * lf.life_qty_marketplace, 0)) AS mplife_cost FROM combined c LEFT JOIN meta_final mfc ON c.sku_group = mfc.sku_group LEFT JOIN sales_l30 l ON c.sku_group = l.sku_group LEFT JOIN sales_l7 l7 ON c.sku_group = l7.sku_group LEFT JOIN sales_life lf ON c.sku_group = lf.sku_group LEFT JOIN t_mp_l30 m30 ON c.sku_group = m30.sku_group LEFT JOIN t_mp_l7 m7 ON c.sku_group = m7.sku_group LEFT JOIN t_mp_life mlf ON c.sku_group = mlf.sku_group ), sales_final AS ( SELECT c.sku_group, COALESCE(l.l30_qty_shopify, 0) AS sales_shopify, COALESCE(l.l30_qty_store, 0) AS sales_store, COALESCE(l.l30_qty_marketplace, 0) AS sales_marketplace, COALESCE(l.l30_qty_total, 0) AS sales_total, COALESCE(l7.l7_qty_shopify, 0) AS sales_l7_shopify, COALESCE(l7.l7_qty_store, 0) AS sales_l7_store, COALESCE(l7.l7_qty_marketplace, 0) AS sales_l7_marketplace, COALESCE(l7.l7_qty_total, 0) AS sales_l7_total, COALESCE(l7.l7_rev_shopify, 0) AS sales_value_l7_shopify, COALESCE(l7.l7_rev_store, 0) AS sales_value_l7_store, COALESCE(l7.l7_rev_marketplace, 0) AS sales_value_l7_marketplace, COALESCE(l7.l7_rev_total, 0) AS sales_value_l7_total, ROUND(COALESCE(l.l30_qty_shopify, 0) / 30.0, 2) AS ros_shopify, ROUND(COALESCE(l.l30_qty_store, 0) / 30.0, 2) AS ros_store, ROUND(COALESCE(l.l30_qty_marketplace, 0) / 30.0, 2) AS ros_marketplace, ROUND(COALESCE(l.l30_qty_total, 0) / 30.0, 2) AS ros_total, CASE WHEN l7.l7_qty_shopify > 0 THEN ROUND(l7.l7_rev_shopify / l7.l7_qty_shopify, 0) END AS asp_l7_shopify, CASE WHEN l7.l7_qty_store > 0 THEN ROUND(l7.l7_rev_store / l7.l7_qty_store, 0) END AS asp_l7_store, CASE WHEN l7.l7_qty_marketplace > 0 THEN ROUND(l7.l7_rev_marketplace / l7.l7_qty_marketplace, 0) END AS asp_l7_marketplace, CASE WHEN l7.l7_qty_total > 0 THEN ROUND(l7.l7_rev_total / l7.l7_qty_total, 0) END AS asp_l7_total, CASE WHEN l.l30_qty_shopify > 0 THEN ROUND(c.wh_inv * 30.0 / l.l30_qty_shopify, 1) END AS doi_shopify, CASE WHEN l.l30_qty_store > 0 THEN ROUND(c.store_inv * 30.0 / l.l30_qty_store, 1) END AS doi_store, CASE WHEN l.l30_qty_marketplace > 0 THEN ROUND(c.wh_inv * 30.0 / l.l30_qty_marketplace, 1) END AS doi_marketplace, CASE WHEN l.l30_qty_total > 0 THEN ROUND(c.grand_total * 30.0 / l.l30_qty_total, 1) END AS doi_total, CASE WHEN c.sku_group LIKE \'FK-%\' OR c.sku_group LIKE \'MP-%\' THEN NULL WHEN COALESCE(wo.open_qty, 0) + COALESCE(so.open_qty, 0) + COALESCE(ins.inward_qty, 0) > 0 THEN ROUND(COALESCE(ss.qty_total, 0) / (COALESCE(wo.open_qty, 0) + COALESCE(so.open_qty, 0) + COALESCE(ins.inward_qty, 0)) * 100, 2) END AS str_pct, CASE WHEN l.l30_rev_shopify > 0 AND mfc.cogs IS NOT NULL THEN ROUND((l.l30_rev_shopify - mfc.cogs * l.l30_qty_shopify) / l.l30_rev_shopify * 100, 2) END AS margin_pct_shopify, CASE WHEN l.l30_rev_store > 0 AND mfc.cogs IS NOT NULL THEN ROUND((l.l30_rev_store - mfc.cogs * l.l30_qty_store) / l.l30_rev_store * 100, 2) END AS margin_pct_store, CASE WHEN mb.mp30_rev > 0 AND mb.mp30_cost IS NOT NULL THEN ROUND((mb.mp30_rev - mb.mp30_cost) / mb.mp30_rev * 100, 2) END AS margin_pct_marketplace, CASE WHEN COALESCE(l.l30_rev_shopify, 0) + COALESCE(l.l30_rev_store, 0) + mb.mp30_rev > 0 THEN ROUND(( (COALESCE(l.l30_rev_shopify, 0) + COALESCE(l.l30_rev_store, 0) + mb.mp30_rev) - (IFF(COALESCE(l.l30_qty_shopify, 0) > 0, mfc.cogs * l.l30_qty_shopify, 0) + IFF(COALESCE(l.l30_qty_store, 0) > 0, mfc.cogs * l.l30_qty_store, 0) + mb.mp30_cost) ) / (COALESCE(l.l30_rev_shopify, 0) + COALESCE(l.l30_rev_store, 0) + mb.mp30_rev) * 100, 2) END AS margin_pct_total, CASE WHEN l7.l7_rev_shopify > 0 AND mfc.cogs IS NOT NULL THEN ROUND((l7.l7_rev_shopify - mfc.cogs * l7.l7_qty_shopify) / l7.l7_rev_shopify * 100, 2) END AS margin_l7_pct_shopify, CASE WHEN l7.l7_rev_store > 0 AND mfc.cogs IS NOT NULL THEN ROUND((l7.l7_rev_store - mfc.cogs * l7.l7_qty_store) / l7.l7_rev_store * 100, 2) END AS margin_l7_pct_store, CASE WHEN mb.mp7_rev > 0 AND mb.mp7_cost IS NOT NULL THEN ROUND((mb.mp7_rev - mb.mp7_cost) / mb.mp7_rev * 100, 2) END AS margin_l7_pct_marketplace, CASE WHEN COALESCE(l7.l7_rev_shopify, 0) + COALESCE(l7.l7_rev_store, 0) + mb.mp7_rev > 0 THEN ROUND(( (COALESCE(l7.l7_rev_shopify, 0) + COALESCE(l7.l7_rev_store, 0) + mb.mp7_rev) - (IFF(COALESCE(l7.l7_qty_shopify, 0) > 0, mfc.cogs * l7.l7_qty_shopify, 0) + IFF(COALESCE(l7.l7_qty_store, 0) > 0, mfc.cogs * l7.l7_qty_store, 0) + mb.mp7_cost) ) / (COALESCE(l7.l7_rev_shopify, 0) + COALESCE(l7.l7_rev_store, 0) + mb.mp7_rev) * 100, 2) END AS margin_l7_pct_total, CASE WHEN lf.life_rev_shopify > 0 AND mfc.cogs IS NOT NULL THEN ROUND((lf.life_rev_shopify - mfc.cogs * lf.life_qty_shopify) / lf.life_rev_shopify * 100, 2) END AS margin_lifetime_pct_shopify, CASE WHEN lf.life_rev_store > 0 AND mfc.cogs IS NOT NULL THEN ROUND((lf.life_rev_store - mfc.cogs * lf.life_qty_store) / lf.life_rev_store * 100, 2) END AS margin_lifetime_pct_store, CASE WHEN mb.mplife_rev > 0 AND mb.mplife_cost IS NOT NULL THEN ROUND((mb.mplife_rev - mb.mplife_cost) / mb.mplife_rev * 100, 2) END AS margin_lifetime_pct_marketplace, CASE WHEN COALESCE(lf.life_rev_shopify, 0) + COALESCE(lf.life_rev_store, 0) + mb.mplife_rev > 0 THEN ROUND(( (COALESCE(lf.life_rev_shopify, 0) + COALESCE(lf.life_rev_store, 0) + mb.mplife_rev) - (IFF(COALESCE(lf.life_qty_shopify, 0) > 0, mfc.cogs * lf.life_qty_shopify, 0) + IFF(COALESCE(lf.life_qty_store, 0) > 0, mfc.cogs * lf.life_qty_store, 0) + mb.mplife_cost) ) / (COALESCE(lf.life_rev_shopify, 0) + COALESCE(lf.life_rev_store, 0) + mb.mplife_rev) * 100, 2) END AS margin_lifetime_pct_total, COALESCE(r.returns_qty, 0) AS returns_qty, CASE WHEN l.l30_qty_total > 0 THEN ROUND(COALESCE(r.returns_qty, 0) / l.l30_qty_total * 100, 2) END AS return_pct, l.l30_rev_shopify AS rev_l30_shopify, l.l30_rev_store AS rev_l30_store, mb.mp30_rev AS rev_l30_marketplace, COALESCE(l.l30_rev_shopify, 0) + COALESCE(l.l30_rev_store, 0) + mb.mp30_rev AS rev_l30_total, IFF(COALESCE(l.l30_qty_shopify, 0) > 0, mfc.cogs * l.l30_qty_shopify, 0) AS cost_l30_shopify, IFF(COALESCE(l.l30_qty_store, 0) > 0, mfc.cogs * l.l30_qty_store, 0) AS cost_l30_store, mb.mp30_cost AS cost_l30_marketplace, IFF(COALESCE(l.l30_qty_shopify, 0) > 0, mfc.cogs * l.l30_qty_shopify, 0) + IFF(COALESCE(l.l30_qty_store, 0) > 0, mfc.cogs * l.l30_qty_store, 0) + mb.mp30_cost AS cost_l30_total, l7.l7_rev_shopify AS rev_l7_shopify, l7.l7_rev_store AS rev_l7_store, mb.mp7_rev AS rev_l7_marketplace, COALESCE(l7.l7_rev_shopify, 0) + COALESCE(l7.l7_rev_store, 0) + mb.mp7_rev AS rev_l7_total, IFF(COALESCE(l7.l7_qty_shopify, 0) > 0, mfc.cogs * l7.l7_qty_shopify, 0) AS cost_l7_shopify, IFF(COALESCE(l7.l7_qty_store, 0) > 0, mfc.cogs * l7.l7_qty_store, 0) AS cost_l7_store, mb.mp7_cost AS cost_l7_marketplace, IFF(COALESCE(l7.l7_qty_shopify, 0) > 0, mfc.cogs * l7.l7_qty_shopify, 0) + IFF(COALESCE(l7.l7_qty_store, 0) > 0, mfc.cogs * l7.l7_qty_store, 0) + mb.mp7_cost AS cost_l7_total, lf.life_rev_shopify AS rev_life_shopify, lf.life_rev_store AS rev_life_store, mb.mplife_rev AS rev_life_marketplace, COALESCE(lf.life_rev_shopify, 0) + COALESCE(lf.life_rev_store, 0) + mb.mplife_rev AS rev_life_total, IFF(COALESCE(lf.life_qty_shopify, 0) > 0, mfc.cogs * lf.life_qty_shopify, 0) AS cost_life_shopify, IFF(COALESCE(lf.life_qty_store, 0) > 0, mfc.cogs * lf.life_qty_store, 0) AS cost_life_store, mb.mplife_cost AS cost_life_marketplace, IFF(COALESCE(lf.life_qty_shopify, 0) > 0, mfc.cogs * lf.life_qty_shopify, 0) + IFF(COALESCE(lf.life_qty_store, 0) > 0, mfc.cogs * lf.life_qty_store, 0) + mb.mplife_cost AS cost_life_total, ROUND(COALESCE(f.f30_qty_shopify, 0) / 30.0, 2) AS f30_ros_shopify, ROUND(COALESCE(f.f30_qty_store, 0) / 30.0, 2) AS f30_ros_store, ROUND(COALESCE(f.f30_qty_marketplace, 0) / 30.0, 2) AS f30_ros_marketplace, ROUND(COALESCE(f.f30_qty_total, 0) / 30.0, 2) AS f30_ros_total FROM combined c LEFT JOIN meta_final mfc ON c.sku_group = mfc.sku_group LEFT JOIN margin_base mb ON c.sku_group = mb.sku_group LEFT JOIN sales_l30 l ON c.sku_group = l.sku_group LEFT JOIN sales_l7 l7 ON c.sku_group = l7.sku_group LEFT JOIN sales_life lf ON c.sku_group = lf.sku_group LEFT JOIN sales_since ss ON c.sku_group = ss.sku_group LEFT JOIN wh_open wo ON c.sku_group = wo.sku_group LEFT JOIN store_open so ON c.sku_group = so.sku_group LEFT JOIN inward_since ins ON c.sku_group = ins.sku_group LEFT JOIN returns_l30 r ON c.sku_group = r.sku_group LEFT JOIN sales_f30 f ON c.sku_group = f.sku_group ), store_ever AS ( SELECT sku_group, COUNT(DISTINCT branch_code) AS stores_ever_sent FROM ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, BRANCH_CODE::VARCHAR AS branch_code, \"DATE\" AS dt, SUM( COALESCE(XS_UNITS,0)+COALESCE(S_UNITS,0)+COALESCE(M_UNITS,0)+COALESCE(L_UNITS,0) +COALESCE(XL_UNITS,0)+COALESCE(XXL_UNITS,0)+COALESCE(XL3_UNITS,0)+COALESCE(XL4_UNITS,0) +COALESCE(XL5_UNITS,0)+COALESCE(XL6_UNITS,0) +COALESCE(JIT_XS_UNITS,0)+COALESCE(JIT_S_UNITS,0)+COALESCE(JIT_M_UNITS,0)+COALESCE(JIT_L_UNITS,0) +COALESCE(JIT_XL_UNITS,0)+COALESCE(JIT_2XL_UNITS,0)+COALESCE(JIT_3XL_UNITS,0)+COALESCE(JIT_4XL_UNITS,0) +COALESCE(JIT_5XL_UNITS,0)+COALESCE(JIT_6XL_UNITS,0) ) AS inv FROM snitch_db.maplemonk.offline_master_daily_report_1 WHERE BRANCH_CODE::VARCHAR NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') GROUP BY 1, 2, 3 ) WHERE inv > 5 GROUP BY sku_group ), myntra_item_map AS ( SELECT ean, MAX(sku) AS sku FROM snitch_db.maplemonk.logic_final_item_master GROUP BY ean ), myntra_base AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(date), \'\'), \'DD-MM-YYYY\') AS date_col, gtin, soh FROM snitch_db.maplemonk.s3_myntra_inventory_test ), myntra AS ( SELECT b.date_col AS date, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(lm.sku), CHARINDEX(\'-\', REVERSE(lm.sku)) + 1, LEN(lm.sku))))) AS sku_group, UPPER(TRIM(REVERSE(SUBSTRING(REVERSE(lm.sku), 1, CHARINDEX(\'-\', REVERSE(lm.sku)) - 1)))) AS raw_size, SUM(COALESCE(b.soh, 0)) AS inv_qty FROM myntra_base b JOIN myntra_item_map lm ON lm.ean = b.gtin GROUP BY 1, 2, 3 ), flipkart_base AS ( SELECT TRY_TO_DATE(NULLIF(TRIM(date), \'\'), \'DD-MM-YYYY\') AS date_col, style_code, size AS raw_size, atp FROM snitch_db.maplemonk.s3_flipkart_inventory_test ), flipkart AS ( SELECT date_col AS date, UPPER(TRIM(style_code)) AS sku_group, UPPER(TRIM(raw_size)) AS raw_size, SUM(COALESCE(atp, 0)) AS inv_qty FROM flipkart_base GROUP BY 1, 2, 3 ), sor_src AS ( SELECT \'MYNTRA\' AS src, sku_group, raw_size, inv_qty FROM myntra WHERE date = (SELECT MAX(date) FROM myntra) AND sku_group IS NOT NULL UNION ALL SELECT \'FLIPKART\', sku_group, raw_size, inv_qty FROM flipkart WHERE date = (SELECT MAX(date) FROM flipkart) AND sku_group IS NOT NULL ), sor_norm AS ( SELECT src, sku_group, CASE WHEN raw_size = \'2XL\' THEN \'XXL\' WHEN raw_size = \'XXXL\' THEN \'3XL\' WHEN raw_size = \'XXU\' THEN \'2XL\' WHEN raw_size = \'28\' THEN \'XS\' WHEN raw_size = \'30\' THEN \'S\' WHEN raw_size = \'32\' THEN \'M\' WHEN raw_size = \'34\' THEN \'L\' WHEN raw_size = \'36\' THEN \'XL\' WHEN raw_size = \'38\' THEN \'XXL\' WHEN raw_size = \'40\' THEN \'3XL\' WHEN raw_size = \'42\' THEN \'4XL\' WHEN raw_size = \'44\' THEN \'5XL\' WHEN raw_size = \'46\' THEN \'6XL\' WHEN raw_size = \'48\' THEN \'7XL\' WHEN raw_size = \'50\' THEN \'8XL\' ELSE raw_size END AS size_norm, inv_qty FROM sor_src ), sor_lkp AS ( SELECT sku_group, SUM(IFF(src = \'MYNTRA\', inv_qty, 0)) AS sor_myntra_inv, SUM(IFF(src = \'FLIPKART\', inv_qty, 0)) AS sor_flipkart_inv, SUM(inv_qty) AS sor_total_inv, SUM(IFF(size_norm = \'XS\', inv_qty, 0)) AS sor_xs, SUM(IFF(size_norm = \'S\', inv_qty, 0)) AS sor_s, SUM(IFF(size_norm = \'M\', inv_qty, 0)) AS sor_m, SUM(IFF(size_norm = \'L\', inv_qty, 0)) AS sor_l, SUM(IFF(size_norm = \'XL\', inv_qty, 0)) AS sor_xl, SUM(IFF(size_norm = \'XXL\', inv_qty, 0)) AS sor_xxl, SUM(IFF(size_norm = \'3XL\', inv_qty, 0)) AS sor_3xl, SUM(IFF(size_norm = \'4XL\', inv_qty, 0)) AS sor_4xl, SUM(IFF(size_norm = \'5XL\', inv_qty, 0)) AS sor_5xl, SUM(IFF(size_norm = \'6XL\', inv_qty, 0)) AS sor_6xl FROM sor_norm GROUP BY sku_group ), collection_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, MAX(collection) AS collection FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 GROUP BY 1 ), flannel_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, MAX(helper1) AS helper1 FROM snitch_db.maplemonk.GS_HC_SKU_REMARKS WHERE upper(helper1) like \'FLANNEL\' GROUP BY 1 ), liquid_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, FROM snitch_db.maplemonk.GS_HC_SKU_REMARKS WHERE upper(REMARK) like \'%LIQU%\' GROUP BY 1 ), winter_lkp AS ( SELECT UPPER(TRIM(sku)) AS sku_group, FROM snitch_db.maplemonk.GS_HC_SKU_REMARKS WHERE upper(REMARK) like \'%WINTER%\' GROUP BY 1 ), img as (with images AS ( SELECT UPPER( TRIM( CASE WHEN variant.value:sku::STRING ILIKE \'4C%\' OR variant.value:sku::STRING ILIKE \'MP%\' THEN REGEXP_SUBSTR(variant.value:sku::STRING, \'^[^-]+-[^-]+-[^-]+\') ELSE REGEXP_SUBSTR(variant.value:sku::STRING, \'^[^-]+-[^-]+\') END ) ) AS sku_group, image.value:preview:image:url::STRING AS image_url, image.index AS image_index FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => PARSE_JSON(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant WHERE image.value:mediaContentType::STRING = \'IMAGE\' ) SELECT sku_group, image_url FROM images QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group ORDER BY image_index ) = 1) SELECT c.sku_group, CASE WHEN wl.sku_group IS NOT NULL THEN \'Winter Wear\' WHEN cl.sku_group IS NOT NULL THEN \'Collection\' WHEN fh.sku_group IS NOT NULL THEN fh.helper1 WHEN upper(PJ.PRODUCT_NAME) LIKE\'%FLANNEL%\' then \'Flannel\' WHEN upper(PJ.PRODUCT_NAME) LIKE\'%TECHNICAL%\' then \'Technical\' ELSE NULL END AS cc2, CASE WHEN fh.sku_group IS NOT NULL THEN \'Flannel\' WHEN LOWER(mf.category) LIKE \'%hoodies%\' OR LOWER(mf.category) LIKE \'%jackets%\' OR LOWER(mf.category) LIKE \'%sweaters%\' OR LOWER(mf.category) LIKE \'%overshirts%\' OR LOWER(mf.category) LIKE \'%overshirt%\' OR LOWER(mf.category) LIKE \'%sweatshirts%\' OR LOWER(mf.category) LIKE \'%trench coat%\' THEN LOWER(mf.category) WHEN cl.sku_group IS NOT NULL THEN cl.collection WHEN upper(PJ.PRODUCT_NAME) LIKE\'%TECHNICAL%\' then \'TECHNICAL\' WHEN upper(PJ.PRODUCT_NAME) LIKE\'%FLANNEL%\' then \'Flannel\' ELSE NULL END AS cc, case when lq.sku_group IS NOT NULL THEN \'2. Liquidation\' else \'1. Non-Liquidation\' end cc3, mf.l1_category, mf.category, mt.meta1, mt.meta2, mt.meta3, mt.meta4, mt.meta5, mf.cogs, mf.mrp, lv.final_live_date AS live_date, iw.last_inward_date, DATEDIFF(day, lv.final_live_date, CURRENT_DATE()) AS days_since_live, DATEDIFF(day, iw.last_inward_date, CURRENT_DATE()) AS days_since_last_inward, al.ageing_bucket, c.total_xs, c.total_s, c.total_m, c.total_l, c.total_xl, c.total_xxl, c.total_3xl, c.total_4xl, c.total_5xl, c.total_6xl, c.total_7xl, c.total_8xl, c.wh_inv, c.store_inv, c.grand_total, CASE WHEN LOWER(mf.l1_category) = \'long_tail\' THEN \'Long Tail\' WHEN LOWER(mf.l1_category) = \'plus\' THEN CASE WHEN total_3xl >= 10 AND total_4xl >= 10 AND total_5xl >= 10 AND total_6xl >= 10 THEN \'Full\' ELSE \'Cut\' END ELSE CASE WHEN total_s >= 10 AND total_m >= 10 AND total_l >= 10 AND total_xxl >= 10 THEN \'Full\' ELSE \'Cut\' END END AS Eco_system_cut_check, CASE WHEN c.grand_total < 100 THEN \'0-100\' WHEN c.grand_total < 300 THEN \'100-300\' WHEN c.grand_total < 500 THEN \'300-500\' WHEN c.grand_total < 800 THEN \'500-800\' WHEN c.grand_total < 1200 THEN \'800-1200\' WHEN c.grand_total < 1600 THEN \'1200-1600\' WHEN c.grand_total < 2000 THEN \'1600-2000\' ELSE \'>2000\' END AS inventory_bucket, CASE WHEN ec.is_excluded THEN NULL WHEN sz.sizes_avl BETWEEN 1 AND 3 AND sz.max_size_share >= 0.5 THEN \'>50% & \' || sz.sizes_avl::VARCHAR || \' size\' WHEN sz.sizes_avl BETWEEN 1 AND 3 THEN sz.sizes_avl::VARCHAR || \' size\' WHEN sz.max_size_share >= 0.5 THEN \'>50% inv\' END AS inventory_remark, ec.size_set_count, CASE WHEN ec.is_excluded THEN \'FULL\' WHEN ec.size_set_count >= 5 THEN \'FULL\' ELSE \'CUT\' END AS size_set_status, ec.size_set_revised, sf.sales_shopify, sf.sales_store, sf.sales_marketplace, sf.sales_total, sf.sales_l7_shopify, sf.sales_l7_store, sf.sales_l7_marketplace, sf.sales_l7_total, sf.sales_value_l7_shopify, sf.sales_value_l7_store, sf.sales_value_l7_marketplace, sf.sales_value_l7_total, sf.ros_shopify, sf.ros_store, sf.ros_marketplace, sf.ros_total, sf.asp_l7_shopify, sf.asp_l7_store, sf.asp_l7_marketplace, sf.asp_l7_total, sf.doi_shopify, sf.doi_store, sf.doi_marketplace, sf.doi_total, sf.str_pct, sf.margin_pct_shopify, sf.margin_pct_store, sf.margin_pct_marketplace, sf.margin_pct_total, sf.margin_l7_pct_shopify, sf.margin_l7_pct_store, sf.margin_l7_pct_marketplace, sf.margin_l7_pct_total, sf.margin_lifetime_pct_shopify, sf.margin_lifetime_pct_store, sf.margin_lifetime_pct_marketplace, sf.margin_lifetime_pct_total, sf.rev_l30_shopify, sf.rev_l30_store, sf.rev_l30_marketplace, sf.rev_l30_total, sf.cost_l30_shopify, sf.cost_l30_store, sf.cost_l30_marketplace, sf.cost_l30_total, sf.rev_l7_shopify, sf.rev_l7_store, sf.rev_l7_marketplace, sf.rev_l7_total, sf.cost_l7_shopify, sf.cost_l7_store, sf.cost_l7_marketplace, sf.cost_l7_total, sf.rev_life_shopify, sf.rev_life_store, sf.rev_life_marketplace, sf.rev_life_total, sf.cost_life_shopify, sf.cost_life_store, sf.cost_life_marketplace, sf.cost_life_total, sf.returns_qty, sf.return_pct, sf.f30_ros_shopify, sf.f30_ros_store, sf.f30_ros_marketplace, sf.f30_ros_total, CASE WHEN GREATEST(sf.f30_ros_store, sf.f30_ros_shopify, sf.f30_ros_marketplace) <= 0 THEN NULL WHEN sf.f30_ros_store = GREATEST(sf.f30_ros_store, sf.f30_ros_shopify, sf.f30_ros_marketplace) THEN \'Store heavy\' WHEN sf.f30_ros_shopify = GREATEST(sf.f30_ros_store, sf.f30_ros_shopify, sf.f30_ros_marketplace) THEN \'Shopify heavy\' ELSE \'MP heavy\' END AS channel_heavy, pl.pipeline_qty, pl.pipeline_order_type, COALESCE(sa.lifetime_store_allocated_qty, 0) AS lifetime_store_allocated_qty, COALESCE(sr.returns_lifetime, 0) AS store_returns_lifetime, osm.offline_inventory_qty, osm.marketplace_mapped_with_stock offline_store_count_current, stz.store_xs, stz.store_s, stz.store_m, stz.store_l, stz.store_xl, stz.store_xxl, stz.store_3xl, stz.store_4xl, stz.store_5xl, stz.store_6xl, COALESCE(se.stores_ever_sent, 0) AS stores_ever_sent, so.sor_myntra_inv, so.sor_flipkart_inv, so.sor_total_inv, so.sor_xs, so.sor_s, so.sor_m, so.sor_l, so.sor_xl, so.sor_xxl, so.sor_3xl, so.sor_4xl, so.sor_5xl, so.sor_6xl, CASE WHEN lv.final_live_date IS NULL THEN \'1. Not live yet\' WHEN lv.final_live_date < \'2026-07-01\' THEN \'3. Old\' ELSE \'2. New\' END AS old_new, image_url FROM combined c LEFT JOIN meta_final mf ON c.sku_group = mf.sku_group LEFT JOIN metafields_lkp mt ON c.sku_group = mt.sku_group LEFT JOIN live_lkp lv ON c.sku_group = lv.sku_group LEFT JOIN inward_agg iw ON c.sku_group = iw.sku_group LEFT JOIN ageing_lkp al ON c.sku_group = al.sku_group LEFT JOIN size_flags sz ON c.sku_group = sz.sku_group LEFT JOIN ecosystem_cut ec ON c.sku_group = ec.sku_group LEFT JOIN sales_final sf ON c.sku_group = sf.sku_group left JOIN pipeline_lkp pl ON c.sku_group = pl.sku_group LEFT JOIN store_alloc sa ON c.sku_group = sa.sku_group LEFT JOIN store_returns sr ON c.sku_group = sr.sku_group LEFT JOIN offline_summary osm ON c.sku_group = osm.sku_group LEFT JOIN collection_lkp cl ON UPPER(TRIM(c.sku_group)) = cl.sku_group LEFT JOIN flannel_lkp fh ON UPPER(TRIM(c.sku_group)) = fh.sku_group LEFT JOIN liquid_lkp lq ON UPPER(TRIM(c.sku_group)) = lq.sku_group LEFT JOIN store_raw stz ON c.sku_group = stz.sku_group LEFT JOIN store_ever se ON c.sku_group = se.sku_group LEFT JOIN sor_lkp so ON c.sku_group = so.sku_group left join snitch_db.maplemonk.product_journey pj on c.sku_group = pj.sku_group left join img on c.sku_group = img.sku_group left join winter_lkp WL on c.sku_group = wl.sku_group WHERE NOT ( REGEXP_LIKE(c.sku_group, \'^8[0-9]*$\') OR UPPER(c.sku_group) LIKE \'PP%\' OR UPPER(c.sku_group) LIKE \'%TEST%\' ) ORDER BY c.grand_total DESC;",
                    "transaction": true
